// function validateAgeGender(age, gender)
// Age < 0 ya > 150: "Invalid age"
// Gender "M"/"F"/"Other": valid
// Baaki: "Invalid gender"
// Sab valid: "Valid"

solution:
function validateAgeGender(age, gender) {
  if (age < 0 || age > 150) return "Invalid age"
  if (gender !== "M" && gender !== "F" && gender !== "Other") return "Invalid gender"
  return "Valid"
}
